const STORAGE_KEY = 'meusObjetos'; // Chave para armazenamento no Local Storage

// Função para obter a lista do Local Storage
export function getObjetos() {
  const objetos = localStorage.getItem(STORAGE_KEY);
  return objetos ? JSON.parse(objetos) : [];
}

// Função para salvar a lista no Local Storage
export function setObjetos(objetos) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(objetos));
}

// Função para adicionar um novo objeto à lista
export function addObjeto(objeto) {
  const objetos = getObjetos();
  objetos.push(objeto);
  setObjetos(objetos);
}

// Função para excluir um objeto da lista (por exemplo, por ID)
export function removeObjeto(id) {
  const objetos = getObjetos();
  const novosObjetos = objetos.filter((obj) => obj.id !== id);
  setObjetos(novosObjetos);
}
